                 size_t size, int flags)
{
    struct sock *sk = sock->sk;
    int ret;

    if (sk->sk_state != TCP_ESTABLISHED)
        return -EINVAL;

    if (flags & ~(MSG_PEEK | MSG_DONTWAIT))
        return -EINVAL;

    ret = sk->sk_prot->recvmsg(iocb, sk, msg, size, flags);
    if (ret < 0)
        return ret;

    if (!(flags & MSG_PEEK)) {
        sock_wfree(sk);
    }

    return ret;
}

int sock_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *msg,
                 size_t size, int flags)
{
    struct sock *sk = sock->sk;
    int error;
    int peeked = flags & MSG_PEEK;
    int copied = 0;

    if (!sock->ops || !sock->ops->recvmsg)
        return -EOPNOTSUPP;

    if (sk->sk_state == TCP_LISTEN)
        return -ECONNREFUSED;

    error = sock->ops->recvmsg(iocb, sock, msg, size, flags, &copied);
    if (error < 0)
        return error;

    if (copied > 0) {
        if (!peeked) {
            sk->sk_rmem_alloc -= copied;
            sock_wfree(sk);
        }
        if (copied > size)
            copied = size;
        if (copied < 0)
            copied = -EFAULT;
    }

    return copied;
}

int recv_from_socket(struct kiocb *iocb, struct socket *sock, struct msghdr *msg, size_t size, int flags) {
    struct sock *sk = sock->sk;
    struct sk_buff *skb;
    int copied = 0;
    int err = 0;

    if (!sk) {
        return -EINVAL;
    }

    skb = skb_dequeue(&sk->sk_receive_queue);
    if (!skb) {
        return -EAGAIN;
    }

    if (size < skb->len) {
        if (!(flags & MSG_TRUNC)) {
            err = -EMSGSIZE;
            goto out_free;
        }
    }

    copied = skb->len;
    if (!(flags & MSG_PEEK)) {
        memcpy(msg->msg_name, skb->cb, sizeof(skb->cb));
        msg->msg_namelen = sizeof(skb->cb);

        if (memcpy_from_msg(msg, skb->data, size)) {
            err = -EFAULT;
            goto out_free;
        }

        skb_pull(skb, size);
        if (skb->len == 0) {
            skb = skb_dequeue(&sk->sk_receive_queue);
        }
    }

    sock_put(sk);
out_free:
    kfree_skb(skb);
    return copied ? copied : err;
}

int receive_message_from_socket(struct kiocb *iocb, struct socket *sock,
                                struct msghdr *msg, size_t size, int flags) {
    struct sock *sk = sock->sk;
    int copied = 0;
    struct sk_buff *skb;

    if (sk->sk_state != TCP_ESTABLISHED)
        return -ENOTCONN;

    if (flags & ~(MSG_PEEK | MSG_DONTWAIT))
        return -EINVAL;

    skb = skb_recv_datagram(sk, flags, &iocb->ki_wait, &copied);
    if (!skb)
        return (copied == 0) ? -EAGAIN : copied;

    if (size < skb->len) {
        if (msg->msg_flags & MSG_TRUNC)
            copied = skb->len;
        else
            copied = size;
    } else {
        copied = skb_copy_datagram_iovec(skb, 0, msg->msg_iov, size);
        if (copied < 0)
            goto out;
    }

    if (!(flags & MSG_PEEK)) {
        skb_free_datagram(sk, skb);
        sock_put(sock);
    }

out:
    return copied;
}
